-- 190: analytics views that read the projection pacing feeds (proj_feed_*), which migration 170 creates after 013 has run, plus COMMENT ON for them.
--   meta_reach                   account-level reach / frequency
--   meta_campaign_daily_history  Meta campaign x day back to 2024-12-31
--   data_coverage                first / last day and freshness of every source (it reads the two feeds above, so it lives here)
--
-- Everything above the "comments" marker is hand-written DDL; everything below it is GENERATED by `python scripts/gen_schema_doc.py --emit-migration 190`
-- from docs/schema/descriptions.py. Additive and idempotent. Once applied this file is immutable (see 013).

-- Account-level reach / frequency (Meta de-duplicates reach itself, so it is stored at each grain and never summed across periods).
-- Comes from the projection pacing feed (fed from the sheet tab 'Meta Account - Reach' today); the current day / week / month is partial.
CREATE OR REPLACE VIEW analytics.meta_reach AS
SELECT r.grain,
       r.period_key,
       r.period_start,
       r.period_end,
       r.impressions,
       r.reach,
       CASE WHEN r.reach > 0 THEN round(r.impressions / r.reach, 4) END AS frequency,
       r.unique_link_clicks,
       r.link_clicks,
       r.unique_outbound_clicks,
       r.loaded_at
FROM public.proj_feed_meta_reach r;

-- Meta campaign x day since 2024-12-31: from 2026-05-06 the same numbers as meta_campaign_daily (source 'app'), before that the sheet's
-- 'Meta Campaign - History' (source 'sheet', campaign grain only, no ad sets or ads). A day is read from 'app' when it has app rows, else from 'sheet'.
CREATE OR REPLACE VIEW analytics.meta_campaign_daily_history AS
SELECT h.day,
       h.campaign_id,
       h.campaign_name,
       h.product,
       h.stage,
       h.source,
       h.spend,
       h.impressions,
       h.link_clicks,
       h.purchases AS meta_purchases,
       h.purchase_value AS meta_revenue
FROM public.proj_feed_meta_day h
WHERE h.source = 'app'
   OR NOT EXISTS (SELECT 1 FROM public.proj_feed_meta_day a WHERE a.day = h.day AND a.source = 'app');

-- One row per data source: first and last day held, rows, when it was last loaded. Read it before quoting "yesterday" or a trailing window.
CREATE OR REPLACE VIEW analytics.data_coverage AS
SELECT 'meta_ad_daily'::text AS source, min(day) AS first_day, max(day) AS last_day, count(DISTINCT day)::int AS days, count(*) AS rows, max(loaded_at) AS loaded_at,
       'Meta Graph API, ad x day, each ad account on its own day (Main = Los Angeles, BackUp = New York); last day = yesterday Pacific, today is never loaded'::text AS note
FROM public.ad_daily
UNION ALL
SELECT 'upstack_meta_attribution', min(day), max(day), count(*)::int, sum(ad_rows), max(pulled_at),
       'Upstack any-click 30-day attribution mapped to Meta ads, Pacific days, the trailing 7 days are re-pulled nightly'
FROM public.upstack_attr_days
UNION ALL
SELECT 'google_campaign_daily', min(day), max(day), count(DISTINCT day)::int, count(*), (SELECT max(pulled_at) FROM public.upstack_google_days),
       'Google spend / impressions / clicks / own conversions (Upstack channel feed) from 2024-03-25, Pacific days'
FROM public.google_daily
UNION ALL
SELECT 'upstack_google_attribution', min(day), max(day), count(*)::int, sum(campaigns), max(pulled_at),
       'Upstack any-click 30-day attribution for Google Ads, Pacific days, from 2025-05-13'
FROM public.upstack_google_days
UNION ALL
SELECT 'orders_daily', min(day), max(day), count(*)::int, count(*), max(pulled_at),
       'Actual revenue and new customers per Pacific day (Upstack orders); the trailing 7 days are restated nightly'
FROM public.upstack_orders_daily
UNION ALL
SELECT 'meta_reach (day grain)', min(period_start), max(period_end), count(*)::int, count(*), max(loaded_at),
       'Account-level impressions / reach; the last day is today and partial'
FROM public.proj_feed_meta_reach WHERE grain = 'day'
UNION ALL
SELECT 'meta_campaign_daily_history', min(day), max(day), count(DISTINCT day)::int, count(*), max(loaded_at),
       'Meta campaign x day from 2024-12-31 (sheet source before 2026-05-06, app source after)'
FROM public.proj_feed_meta_day;

-- ---------------------------------------------------------------- comments
COMMENT ON VIEW analytics.meta_campaign_daily_history IS 'Meta campaign x day back to 2024-12-31: the only Meta data before 2026-05-06 (campaign grain, no ad sets or ads). From 2026-05-06 on it equals meta_campaign_daily''s Meta-reported columns. Grain: one row per (day, campaign_id) after the day rule (a day is read from ''app'' when it has app rows, else from ''sheet''). Source: public.proj_feed_meta_day: ''app'' = aggregated from ad_daily by the app, ''sheet'' = the Lonvera Projections sheet tab ''Meta Campaign - History''. Refresh: nightly (etl service 13:00 UTC via etl.projection_daily); sheet rows never change after the backfill. Coverage: 2024-12-31 through yesterday (Pacific). Caveats: Meta-reported only (no Upstack columns). product and stage are classified from the CAMPAIGN NAME here (''VitaBull'', ''Beef Liver'', ''Boneflex'', ''Unclassified''; ''Testing'' / ''Scaling''), not through the tracker, so they can differ from analytics.meta_ads.product_slug. | Use it for trends across the May 2026 boundary; the ad-grain views cannot go back that far.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.day IS 'Calendar day.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.campaign_name IS 'Campaign name.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.product IS 'Product guessed from the campaign name: VitaBull | Beef Liver | Boneflex | Unclassified.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.stage IS '''Testing'' when the campaign name contains ''test'', else ''Scaling'' (capitalised here).';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.source IS '''app'' (aggregated from ad_daily) or ''sheet'' (the sheet''s campaign history).';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.impressions IS 'Meta impressions.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.link_clicks IS 'Meta link clicks.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.meta_purchases IS 'Meta-reported purchases.';
COMMENT ON COLUMN analytics.meta_campaign_daily_history.meta_revenue IS 'Meta-reported purchase value, dollars.';
COMMENT ON VIEW analytics.meta_reach IS 'Account-level reach and frequency for Meta (both ad accounts summed). Reach is de-duplicated by Meta per period, so it is stored at each grain and must never be summed across days or weeks. Grain: one row per (grain, period_key): grain is ''day'', ''week'' (ISO) or ''month''. Source: public.proj_feed_meta_reach (sheet tab ''Meta Account - Reach'' today; the feeds service writes a shadow copy in proj_feedx_meta_reach). Refresh: nightly (etl service via etl.projection_daily); the trailing days are replaced. Coverage: day 2025-01-01.., week 2024-12-30.., month 2025-01-01..; the current day, week and month are partial. Caveats: Account level only: there is NO reach / frequency per ad, ad set, campaign or product (the product table, proj_feed_product_reach, holds unique outbound clicks only). | The last day is today (partial). Compare complete periods only. | frequency = impressions / reach, computed here (NULL when reach is 0).';
COMMENT ON COLUMN analytics.meta_reach.grain IS '''day'' | ''week'' | ''month''.';
COMMENT ON COLUMN analytics.meta_reach.period_key IS '''2026-11-02'' (day) | ''2026-W45'' (ISO week) | ''2026-11'' (month).';
COMMENT ON COLUMN analytics.meta_reach.period_start IS 'First day of the period.';
COMMENT ON COLUMN analytics.meta_reach.period_end IS 'Last day of the period (the current period ends today and is partial).';
COMMENT ON COLUMN analytics.meta_reach.impressions IS 'Meta impressions over the period.';
COMMENT ON COLUMN analytics.meta_reach.reach IS 'People reached over the period (Meta de-duplicated; not additive across periods).';
COMMENT ON COLUMN analytics.meta_reach.frequency IS 'impressions / reach, 4 decimals.';
COMMENT ON COLUMN analytics.meta_reach.unique_link_clicks IS 'Unique link clicks over the period.';
COMMENT ON COLUMN analytics.meta_reach.link_clicks IS 'Link clicks over the period.';
COMMENT ON COLUMN analytics.meta_reach.unique_outbound_clicks IS 'Unique outbound clicks over the period (Meta de-duplicated).';
COMMENT ON COLUMN analytics.meta_reach.loaded_at IS 'When the row was loaded.';
COMMENT ON VIEW analytics.data_coverage IS 'Freshness and coverage per data source: first and last day held, days, rows, when last loaded. Read it before quoting ''yesterday'' or a trailing window. Grain: one row per source. Source: min / max of each source table''s day column. Refresh: live (computed on every query). Coverage: all sources. Caveats: last_day is the last day LOADED. For Meta, Upstack, Google and orders that is yesterday Pacific; today is never loaded. The meta_reach day grain ends today and the last row is partial. | The last 3 to 7 days still move: Meta restates conversions for weeks (28 trailing days re-pulled nightly), Upstack and orders re-pull 7 days.';
COMMENT ON COLUMN analytics.data_coverage.source IS 'meta_ad_daily | upstack_meta_attribution | google_campaign_daily | upstack_google_attribution | orders_daily | meta_reach (day grain) | meta_campaign_daily_history.';
COMMENT ON COLUMN analytics.data_coverage.first_day IS 'First day held.';
COMMENT ON COLUMN analytics.data_coverage.last_day IS 'Last day held.';
COMMENT ON COLUMN analytics.data_coverage.days IS 'Distinct days held.';
COMMENT ON COLUMN analytics.data_coverage.rows IS 'Rows (or ad rows) held.';
COMMENT ON COLUMN analytics.data_coverage.loaded_at IS 'Latest load / pull time of the source.';
COMMENT ON COLUMN analytics.data_coverage.note IS 'Timezone and refresh note for the source.';
